// V-B2-01 (excerpt; full file was saved to the scratchpad as verify-b2.test.ts)
const N = 16; const w = new World({ seed: 'vb2-01', n: 3, t: 2, voters: N });
await w.start(); await w.setupOrgAndElection(); await w.registerVoters(); await w.publishManifest(); await w.ceremony();
assert.equal((await w.open()).status, 201);
for (let i = 0; i < N; i++) assert.equal((await w.cast(i, { budget: ['yes'], chair: ['ann'] })).status, 201);
assert.equal((await w.close()).status, 201);
const url = `/api/v1/elections/${w.electionId}/tally/draft`;
const probe = async (path) => { const t0 = performance.now();
  const [r, hz] = await Promise.all([ w.get(path).then((x) => ({ x, ms: performance.now() - t0 })),
    new Promise((res) => setTimeout(res, 1)).then(async () => { await w.get('/healthz'); return performance.now() - t0; }) ]);
  return { r: r.x, ms: r.ms, hz }; };
const base = await probe(`/api/v1/elections/${w.electionId}/state`);
const runs = []; for (let k = 0; k < 3; k++) { const p = await probe(url); assert.equal(p.r.status, 409);
  assert.match(p.r.text, /E_TALLY_INSUFFICIENT/); runs.push(p.ms); }
assert.ok(Math.min(...runs) - base.ms > 1.5 * N); // aggregate recomputed every call
await w.server.stop(); await w.start(); await probe(`/api/v1/elections/${w.electionId}/state`);
const cold = await probe(url); const warm = await probe(url);
assert.ok(cold.ms > 3 * warm.ms);          // analysis (proof verification) redone after restart
assert.ok(cold.hz >= cold.ms * 0.8);        // /healthz blocked for the duration

