test('V-B2-12', { timeout: 300_000 }, async (t) => {
  const zeroPk = ed25519Keypair(new Uint8Array(32)).publicKey;
  const check = (j: any, logPk: Uint8Array) => {
    const msg = promiseMessage(j.origin, j.seq, Buffer.from(j.leaf_hash, 'base64url'), j.promise.sequenced_at, j.promise.checkpoint_deadline);
    const sig = Buffer.from(j.promise_sig, 'base64url');
    return { real: ed25519Verify(logPk, sig, msg), zero: ed25519Verify(zeroPk, sig, msg) };
  };
  const A = await fullElection('v12-src'); // runs to audit_close (ARCHIVED)
  try {
    const logPk = new Uint8Array(Buffer.from(A.logPkHex, 'hex'));
    const e = (await A.get(`/api/v1/elections/${A.electionId}/log/entries?from=1&limit=1`)).json.entries[0];
    const post = (W: World, id: string) => W.req('POST', `/api/v1/elections/${id}/log/entries`, { header: e.header_b64u, body: e.body_b64u });
    const live = await post(A, A.electionId); assert.equal(live.status, 200);
    const cLive = check(live.json.receipt, logPk);
    const bytes = await exportQvb(A);
    await A.server.stop(); await A.start(); // restart: keys were erased at ARCHIVED
    const arch = await post(A, A.electionId); assert.equal(arch.status, 200);
    const cArch = check(arch.json.receipt, logPk);
    const B = new World({ seed: 'v12-dst', n: 3, t: 2, voters: 1 });
    await B.start();
    try {
      await B.setupOrgAndElection();
      const job = await importAndWait(B, bytes); assert.equal(job.state, 'done');
      const m = await post(B, job.result.election_id); assert.equal(m.status, 200);
      const cMir = check(m.json.receipt, logPk);
      assert.deepEqual(cLive, { real: true, zero: false });
      assert.deepEqual(cArch, { real: false, zero: true });
      assert.deepEqual(cMir, { real: false, zero: true });
    } finally { await B.stop(); }
  } finally { await A.stop(); }
});

