import test, { after, before } from 'node:test';
import assert from 'node:assert/strict';
import { World } from './helpers/world.ts';
let w: World; let calls = 0;
before(async () => {
  w = new World({ seed: 'vb217', n: 3, t: 2, voters: 2 });
  await w.start(); await w.setupOrgAndElection(); await w.publishManifest();
  const rt = (await (w as any).server.pool.get(w.electionId))!;
  const orig = rt.edb.entries.bind(rt.edb);
  rt.edb.entries = (...a: unknown[]) => { calls++; return orig(...a); };
}, { timeout: 60_000 });
after(async () => { await w.stop(); });
const get = async (p: string, h: Record<string, string> = {}) => { const r = await fetch(w.base + p, { headers: h }); await r.arrayBuffer(); return { status: r.status, etag: r.headers.get('etag')! }; };
