  const j = `/api/v1/elections/${w.electionId}/export.json`, q = `/api/v1/elections/${w.electionId}/export.qvb`;
  const first = await get(j); assert.equal(first.status, 200); const base = calls;
  assert.equal((await get(j, { 'if-none-match': first.etag })).status, 304); const a = calls;
  assert.equal((await get(j, { range: 'bytes=0-9' })).status, 206); const b = calls;
