test('shred on a symlink overwrites the target file, unlinks only the link', async () => {
  const d = mkdtempSync(join(tmpdir(), 'vtr08-'));
  try {
    const victim = join(d, 'unrelated.txt'); writeFileSync(victim, 'SYNTHETIC-UNRELATED-CONTENT');
    const backup = join(d, 'backup.qvb'); symlinkSync(victim, backup);
    assert.equal(await shred(backup, (n) => new Uint8Array(n).fill(0x41)), true);
    assert.equal(existsSync(backup), false);
    assert.ok(lstatSync(victim).isFile());
    assert.equal(readFileSync(victim, 'utf8'), 'A'.repeat('SYNTHETIC-UNRELATED-CONTENT'.length));
  } finally { rmSync(d, { recursive: true, force: true }); }
});
