const L = 2n ** 252n + 27742317777372353535851937790883648493n;
const leToBig = (b: Uint8Array) => b.reduceRight((a, x) => (a << 8n) | BigInt(x), 0n);
const bigToLe32 = (n: bigint) => { const o = new Uint8Array(32); for (let i = 0; i < 32; i++) { o[i] = Number(n & 255n); n >>= 8n; } return o; };
test('M14: small-order R rejected', () => {
  const kp = ed25519Keypair(new Uint8Array(32).fill(7));
  const msg = new TextEncoder().encode('synthetic message');
  const { scalar } = ed25519.utils.getExtendedPublicKey(kp.secretKey);
  const R = new Uint8Array(32); R[0] = 1; // identity
  const k = leToBig(sha512(new Uint8Array([...R, ...kp.publicKey, ...msg]))) % L;
  const sig = new Uint8Array([...R, ...bigToLe32((k * scalar) % L)]);
  assert.equal(ed25519.verify(sig, msg, kp.publicKey, { zip215: false }), true);
  assert.equal(ed25519Verify(kp.publicKey, sig, msg), false);
});
