import { baseMul, constantRng, decProve, decVerify, elgamalEncrypt, scalarMul, scalarRandomNonZero, scalarSub, streamRng, ORDER } from '../packages/crypto/src/index.ts';
const modInv = (a: bigint, n: bigint) => { let [r0, r1, s0, s1] = [((a % n) + n) % n, n, 1n, 0n]; while (r1) { const q = r0 / r1; [r0, r1] = [r1, r0 - q * r1]; [s0, s1] = [s1, s0 - q * s1]; } return ((s0 % n) + n) % n; };
test('B1-12', () => {
  const rng = streamRng('vpoc-b1-12');
  const K = baseMul(scalarRandomNonZero(rng));
  const ctx = new Uint8Array(32).fill(9); // synthetic
  const sj = scalarRandomNonZero(rng); const Yj = baseMul(sj);
  const ct1 = elgamalEncrypt(K, 3, scalarRandomNonZero(rng));
  const ct2 = elgamalEncrypt(K, 4, scalarRandomNonZero(rng));
  const p1 = decProve({ ctx, cid: 'c', oid: 'o', j: 1, Yj, A: ct1.A, B: ct1.B }, sj, constantRng(7));
  const p2 = decProve({ ctx, cid: 'c', oid: 'o', j: 1, Yj, A: ct2.A, B: ct2.B }, sj, constantRng(7));
  assert.ok(decVerify({ ctx, cid: 'c', oid: 'o', j: 1, Yj, A: ct1.A, B: ct1.B, M: p1.M }, p1.proof));
  assert.ok(decVerify({ ctx, cid: 'c', oid: 'o', j: 1, Yj, A: ct2.A, B: ct2.B, M: p2.M }, p2.proof));
  const rec = scalarMul(scalarSub(p1.proof.s, p2.proof.s), modInv(scalarSub(p1.proof.c, p2.proof.c), ORDER));
  assert.equal(rec, sj);
});
